-- =============================================================================
-- University of Nigeria, Nsukka — Faculty of Social Sciences —
-- Religion and Cultural Studies
-- Course outlines transcribed from the Faculty of Social Sciences course
-- handbook (scanned copy), covering the "B.A. Four-Year Standard Programme:
-- Religion and Cultural Studies": all four years, both semesters, including
-- required ancillary, general-studies and elective courses.
-- =============================================================================
-- Run in the Supabase SQL Editor. Safe to run more than once: existing rows
-- for this department are removed first, so it updates rather than duplicates.
--
-- SEMESTERS: the handbook explicitly labels every course "FIRST SEMESTER" or
-- "SECOND SEMESTER" in its programme-structure tables, so those stated values
-- are used directly — no guessing was needed here.
--
-- One elective sub-list at 200 Level first semester (a "choose two" block
-- including an Igbo-language code and an alternate Biblical-Greek proficiency
-- track) was printed across a page fold badly enough that two of its six
-- entries could not be matched to a confident code; only the four
-- unambiguous options (HIS 111, SOC 203, PHL 251, PSY 261) are included
-- rather than guessing at the other two.
--
-- ANCILLARY/GSP/ELECTIVE COURSES FROM OTHER DEPARTMENTS: courses such as
-- ACH 101/212, ECO 101/211, FRE 101, PHL 101/251/351, ANT 102, GSP 1xx/2xx,
-- HIS 111/311, SOC 203, IGB 202/332 and COS 101/304 appear in the Religion
-- and Cultural Studies timetable but their own descriptions are not printed
-- in this section of the document, so they carry real code/title/units only,
-- description left blank pending a verified source elsewhere in this app.
-- =============================================================================

delete from public.course_outlines
 where institution = 'University of Nigeria, Nsukka'
   and department = 'Religion and Cultural Studies';

insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level,
   semester, credit_units, description, topics, contributor_name)
values
  ('RCS 101', 'Introduction to the Study of Religion', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'first', 2, 'This course of study serves as a general introduction to the comparative study of major religious experiences, with special emphasis on common features found in religious beliefs and practices. The essence is to study religion as a universal phenomenon. It introduces students to the various definitions of religion from the sociological, cultural and psychological points of view. Keywords include theism, revelation, worship, sacred and profane, symbolism, taboos, myths, and religious language. Uses and abuses of religion in the society are considered.', '["This course of study serves as a general introduction to the comparative study of major religious experiences, with special emphasis on common features found in religious beliefs and practices", "The essence is to study religion as a universal phenomenon", "It introduces students to the various definitions of religion from the sociological, cultural and psychological points of view", "Keywords include theism, revelation, worship, sacred and profane, symbolism, taboos, myths, and religious language", "Uses and abuses of religion in the society are considered"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 111', 'Background of the Old Testament', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'first', 2, 'The Old Testament documents and people did not develop ex-nihilo. Their lives and traditions developed from other Ancient Near Eastern peoples. This explains why some materials in the Old Testament resemble some documents from the Ancient Near East. The course, therefore, studies some archaeological documents that bear semblance with the Old Testament materials especially those from Mari, Nuzi, Ugarit Tell-el –Amarna, etc.', '["The Old Testament documents and people did not develop ex-nihilo. Their lives and traditions developed from other Ancient Near Eastern peoples", "This explains why some materials in the Old Testament resemble some documents from the Ancient Near East", "The course studies some archaeological documents that bear semblance with the Old Testament materials, especially those from Mari, Nuzi, Ugarit Tell-el –Amarna, etc"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 121', 'Basic Biblical Greek I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'first', 2, 'This course covers the basic grammar of the language with frequent exercises in translation from Greek into English and from English into Greek. Basic English Grammar is revised as a pre-requisite to basic Greek grammar. The following topics are taught, Diphthongs, Breathings, Elision and Diaeresis, punctuations, iota subscript, crasis, movable consonants -v, and accents. Verbs to be taught include Present, Imperfect and Future Indicative Active.', '["This course covers the basic grammar of the language with frequent exercises in translation from Greek into English and from English into Greek", "Basic English Grammar is revised as a pre-requisite to basic Greek grammar", "Topics taught: Diphthongs, Breathings, Elision and Diaeresis, punctuations, iota subscript, crasis, movable consonants -v, and accents", "Verbs to be taught include Present, Imperfect and Future Indicative Active"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 123', 'The Background of the New Testament', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'first', 2, 'The course covers the cultural, literary and ideological background of Palestinian Judaism into which Jesus Christ was born emphasizing the conflict between Judaism and Rome, the Rabbis and Sects and the Parties, their influence in first century Judaism, the writings and apocalyptic literature, the message and method of apocalyptic as they relate to the Tradition of the Elders during the time of Jesus.', '["The course covers the cultural, literary and ideological background of Palestinian Judaism into which Jesus Christ was born, emphasizing the conflict between Judaism and Rome", "The Rabbis and Sects and the Parties, their influence in first century Judaism", "The writings and apocalyptic literature, the message and method of apocalyptic as they relate to the Tradition of the Elders during the time of Jesus"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 151', 'Introduction to African Traditional Religion', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'first', 2, 'This course will expose students to an overview of the traditional religion of Africa (ATR). Emphasis will be laid on such general topics like the definition and characteristic features of ATR, problems of nomenclature; sources; some elements in the structure and the relevance of ATR in contemporary African situation.', '["This course will expose students to an overview of the traditional religion of Africa (ATR)", "Emphasis will be laid on such general topics like the definition and characteristic features of ATR, problems of nomenclature; sources", "Some elements in the structure and the relevance of ATR in contemporary African situation"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 102', 'Field Trip and Tutorial I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'second', 2, 'The Course attempts to acquaint students with ancient religious centres, museums, religious institutions, ecumenical centres and religious personalities whose wealth of experience will expose students to better understanding of religion.', '["The Course attempts to acquaint students with ancient religious centres, museums, religious institutions, ecumenical centres and religious personalities", "Whose wealth of experience will expose students to better understanding of religion"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 112', 'Introduction to the Study of the Old Testament', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'second', 2, 'The course introduces students to the modern Old Testament criticism beginning with the Textual criticism, Tradico-Historical method to Historical-critical methods. The course also looks at the contributions of scholars like J. Morinus, L. Capellus, G.W.F. Hegel, J. Wellhausen, Gunkel and Scandinavian scholars.', '["The course introduces students to the modern Old Testament criticism beginning with the Textual criticism, Tradico-Historical method to Historical-critical methods", "The course also looks at the contributions of scholars like J. Morinus, L. Capellus, G.W.F. Hegel, J. Wellhausen, Gunkel and Scandinavian scholars"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 122', 'Basic Biblical Greek II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'second', 2, 'This is a continuation of REL 121 and in addition, more Greek exercises on translation are drawn from the New Testament Greek Text. Present and Imperfect Indicative Passive, Adjectives in masculine, feminine and neuter, Prepositions, Conjunctions. Nouns include Second and First Declensions, Articles. Further uses of Cases and simple sentences are made. Verb-to-be are included here.', '["This is a continuation of REL 121 and in addition, more Greek exercises on translation are drawn from the New Testament Greek Text", "Present and Imperfect Indicative Passive, Adjectives in masculine, feminine and neuter, Prepositions, Conjunctions", "Nouns include Second and First Declensions, Articles. Further uses of Cases and simple sentences are made. Verb-to-be are included here"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 124', 'Introduction to the Tradition of Jesus', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'second', 2, 'This course is designed to acquaint students with the development of Jesus'' traditions, Messiahship, introduction to Gospel criticisms — Form Criticism, Literary Criticism, Source Criticism, Textual Criticism, Redaction criticism – or inspiration/ inerrancy of the New Testament books as the Synoptic problem and the writing of the New Testament books from Canon, Messianic secrets of Mark are also examined.', '["This course is designed to acquaint students with the development of Jesus'' traditions, Messiahship, introduction to Gospel criticisms — Form Criticism, Literary Criticism, Source Criticism", "Textual Criticism, Redaction criticism – or inspiration/ inerrancy of the New Testament books", "The Synoptic problem and the writing of the New Testament books from Canon, Messianic secrets of Mark are also examined"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 142', 'Religion and Human Values I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'second', 2, 'This course aims at emphasizing human dignity as opposed to more technological advantages man may accrue, important as they are, the population of religious traditions, oral or written which sanction this emphasis- Ethics of chauvinism and U.N. Human Rights.', '["This course aims at emphasizing human dignity as opposed to more technological advantages man may accrue, important as they are", "The population of religious traditions, oral or written which sanction this emphasis - Ethics of chauvinism and U.N. Human Rights"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 211', 'Introduction to Old Testament Hebrew', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'first', 2, 'The course introduces the students to the structure and working vocabulary of Hebrew. Alphabets, points, principles of the syllable, vowel sounds sign in Hebrew (Meqeqph & Metegh); Personal, Demonstrative, Interrogative and other pronouns; simple forms of the verb, the perfect and imperfect.', '["The course introduces the students to the structure and working vocabulary of Hebrew", "Alphabets, points, principles of the syllable, vowel sounds sign in Hebrew (Meqeqph & Metegh)", "Personal, Demonstrative, Interrogative and other pronouns; simple forms of the verb, the perfect and imperfect"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 213', 'The People of the Old Testament: Their History', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'first', 2, 'The course familiarizes the students with the History of the Ancient Near Eastern people as it concerns the people of Israel. This takes the students through the life of the Patriarch, the era of tribal amphictyony, the Monarchy to the exile of the two Hebrew Kingdoms.', '["The course familiarizes the students with the History of the Ancient Near Eastern people as it concerns the people of Israel", "This takes the students through the life of the Patriarch, the era of tribal amphictyony, the Monarchy to the exile of the two Hebrew Kingdoms"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 223', 'Geo-Cultural Setting of Palestine', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'first', 2, 'The course examines the geography and climate, roads and hill paths, towns and villages, Houses, Clothes, Food and Drink, Education, flowers and birds of Palestine during the time of Jesus. Two centres of Jesus'' Ministry – Capernaum and his neighbourhood as well as Jerusalem (the last week) are examined. This will help the student to appreciate why some critical statements were made by the New Testament characters.', '["The course examines the geography and climate, roads and hill paths, towns and villages, Houses, Clothes, Food and Drink, Education, flowers and birds of Palestine during the time of Jesus", "Two centres of Jesus'' Ministry – Capernaum and his neighbourhood as well as Jerusalem (the last week) are examined", "This will help the student to appreciate why some critical statements were made by the New Testament characters"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 231', 'Christian History and Doctrine I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'first', 2, 'The course traces the history of the Primitive Church from the close of the Apostolic Age to the fall of the Western Roman Empire in 451 A.D. Special reference is made to the relations of Church and State, the internal organization of the Church, the Roman Primacy, and the doctrinal controversies within the period.', '["The course traces the history of the Primitive Church from the close of the Apostolic Age to the fall of the Western Roman Empire in 451 A.D", "Special reference is made to the relations of Church and State, the internal organization of the Church, the Roman Primacy", "The doctrinal controversies within the period"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 251', 'African Traditional Religion I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'first', 2, 'This course offers special studies in the nature of African traditional religion; belief in Supreme God; existence and worship; belief in minor divinities; ancestral cult and reincarnation; priesthood, rites of passage, oracles and divination; secret societies, charms and magic, witchcraft and the future of African traditional religion.', '["This course offers special studies in the nature of African traditional religion; belief in Supreme God; existence and worship", "Belief in minor divinities; ancestral cult and reincarnation; priesthood, rites of passage, oracles and divination", "Secret societies, charms and magic, witchcraft and the future of African traditional religion"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 261', 'Religious Ethics I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'first', 2, 'The course is designed to offer special studies in the origin, definitions and classification of ethical systems; morality and religion; biblical ethics, traditional African ethics and values; conscience, the state and positive law and the democratic ideals.', '["The course is designed to offer special studies in the origin, definitions and classification of ethical systems", "Morality and religion; biblical ethics, traditional African ethics and values", "Conscience, the state and positive law and the democratic ideals"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 204', 'Field Trip and Tutorial II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'second', 2, 'Students are taught how to examine religious and cultural relics, museums, traditional religious centres, and institutions that will be visited by the students to familiarize themselves with the major religions in Nigeria and the sacred objects with which they value very highly. Students are required to present written observations during fieldwork.', '["Students are taught how to examine religious and cultural relics, museums, traditional religious centres, and institutions that will be visited by the students to familiarize themselves with the major religions in Nigeria", "The sacred objects with which they value very highly", "Students are required to present written observations during fieldwork"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 206', 'Problems of Religious Beliefs and History', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'second', 2, 'The course aims at exposing students to various problems which have relevance to the reality and relevance of history to helping to find some helpful solutions. Some major religions in Nigeria and their common features, history and tenets will be taught, and major causes of religious conflicts and problems will also be examined. Possible solutions will also be proffered.', '["The course aims at exposing students to various problems which have relevance to the reality and relevance of history to helping to find some helpful solutions", "Some major religions in Nigeria and their common features, history and tenets will be taught", "Major causes of religious conflicts and problems will also be examined. Possible solutions will also be proffered"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 212', 'Elements of Hebrew Grammar', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'second', 2, 'The course is an inseparable pair of Rel. 211. It widens students'' knowledge on such issue as: Inseparable preposition, The Noun, Inflection, construct state, pronominal suffixes, the imperative, infinitive and participle, The Jussive, Cohortative and waw consecutive, paradigm of the regular verb; The simple reflexive -Niphal, The intensive, active, passive and reflexive-perfect, pu''al and Hithpael.', '["The course is an inseparable pair of Rel. 211. It widens students'' knowledge on such issue as: Inseparable preposition, The Noun, Inflection, construct state, pronominal suffixes", "The imperative, infinitive and participle, The Jussive, Cohortative and waw consecutive", "Paradigm of the regular verb; The simple reflexive -Niphal, The intensive, active, passive and reflexive-perfect, pu''al and Hithpael"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 214', 'Exilic and Post Exilic Israel', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'second', 2, 'The course starts with historical reconstruction of the exilic-era, the early post- exilic period and reconstruction under Nehemiah and Ezra. The history of the Jews under the Persians, The history of the Jews under the Greeks: From Alexander to Seleucid domination, The Maccabean revolt and the Hasmonean.', '["The course starts with historical reconstruction of the exilic-era, the early post-exilic period and reconstruction under Nehemiah and Ezra", "The history of the Jews under the Persians", "The history of the Jews under the Greeks: From Alexander to Seleucid domination, The Maccabean revolt and the Hasmonean"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 224', 'Traditions of Jesus', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'second', 2, 'This course examines the main teachings and miracles of Jesus, discipleship, Sermon on the Mount, the figurative use of mountains and cloud in the Bible, Jesus'' confrontations with religious and socio-political leaders, Son of God, Son of Man, Lord etc. Deliberate attempts are made to relate these teachings and life mission of Jesus Christ to the socio-economic and political situations of modern African society.', '["This course examines the main teachings and miracles of Jesus, discipleship, Sermon on the Mount, the figurative use of mountains and cloud in the Bible", "Jesus'' confrontations with religious and socio-political leaders, Son of God, Son of Man, Lord etc", "Deliberate attempts are made to relate these teachings and life mission of Jesus Christ to the socio-economic and political situations of modern African society"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 272', 'History of Islam in West Africa', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'second', 2, 'This is an introductory course, which covers the advent and propagation of Islam in the Empires of the Sudan. The course is a historical survey of the introduction and progress of Islam in the ancient Kingdoms of Songhay, Ghana, Mali and Bornu-Kanem Emirates. Included in the subject matter is an examination of the cultural, religious and social factors responsible for the spread of Islam, and the impact of the religion on West African region. In addition the course is intended to modern methods of propagating Islam such as educational institutions, mass media, conferences, seminars and the internet.', '["This is an introductory course, which covers the advent and propagation of Islam in the Empires of the Sudan", "The course is a historical survey of the introduction and progress of Islam in the ancient Kingdoms of Songhay, Ghana, Mali and Bornu-Kanem Emirates", "An examination of the cultural, religious and social factors responsible for the spread of Islam, and the impact of the religion on West African region", "The course is intended to modern methods of propagating Islam such as educational institutions, mass media, conferences, seminars and the internet"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 221', 'Advanced Biblical Greek I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'first', 2, 'The students are introduced to the syntax of new Testament Greek, temporal clauses, reported speech, indirect questions and commands, the subjunctive and optative moods, final clauses with present in meaning. Periphrastic constructions are also employed to help students translate from English to Greek and vice versa; Imperative, Infinitive, Middle Voice, Perfect and Pluperfect, Participles, Third Declension and more Parsing.

Prerequisites: REL 121, 123', '["The students are introduced to the syntax of new Testament Greek, temporal clauses, reported speech, indirect questions and commands, the subjunctive and optative moods, final clauses with present in meaning", "Periphrastic constructions are also employed to help students translate from English to Greek and vice versa", "Imperative, Infinitive, Middle Voice, Perfect and Pluperfect, Participles, Third Declension and more Parsing"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 222', 'Advanced Biblical Greek II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'second', 2, 'This course is an Introduction to textual criticism. Greek texts of selected passages of St. Mark are studied. Methods of preservation of the original traditions of Jesus are examined. The following are defined, conflation, haplography, dittography, palimpsest, codex, miniscule, itacism, interpolation, manuscript evidence, the use of an apparatus. Textual Apparatus to solve textual problems form major part of the course. Deciding on a variant text is required. Authorship, Date and Content of Mark''s Gospel are considered.', '["This course is an Introduction to textual criticism. Greek texts of selected passages of St. Mark are studied", "Methods of preservation of the original traditions of Jesus are examined: conflation, haplography, dittography, palimpsest, codex, miniscule, itacism, interpolation, manuscript evidence, the use of an apparatus", "Textual Apparatus to solve textual problems form major part of the course. Deciding on a variant text is required", "Authorship, Date and Content of Mark''s Gospel are considered"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 262', 'Ethical and Basic Principles of Counselling', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'first', 2, 'The course introduces the students to the core principles, the basic goals of counselling and the ethics relating to counselling skills. The focus is to prepare students for various methods of anxiety, anger, depression and marital problems. The aim is to help individual students to understand themselves, to help one another and to develop counselling skill.', '["The course introduces the students to the core principles, the basic goals of counselling and the ethics relating to counselling skills", "The focus is to prepare students for various methods of anxiety, anger, depression and marital problems", "The aim is to help individual students to understand themselves, to help one another and to develop counselling skill"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 313', 'Religion of the Old Testament', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'first', 2, 'This is a brief study of the theories of origin of Old Testament religion. This will be studied under (a) Religion of the Patriarchs, (b) Mosaic Yahweism, (c) Religion under the crown and (d) Major changes of Israel''s religion during the exile.', '["This is a brief study of the theories of origin of Old Testament religion", "Studied under (a) Religion of the Patriarchs, (b) Mosaic Yahweism, (c) Religion under the crown", "(d) Major changes of Israel''s religion during the exile"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 321', 'Earliest Christianity: The Beginnings', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'first', 2, 'This course focuses students'' attention on the beginnings of Christianity emphasizing development of the theological thoughts on the Kingdom of God, Synoptic kerygma and the Church changing from a religious movement to religious institution, their failure to the Jews, the Fall of Jerusalem in 70 AD, Hellenistic Christianity and Jewish Christianity, factors that helped the spread of Christianity, re-interpretation of Jesus traditions in the light of Easter experience are taught.', '["This course focuses students'' attention on the beginnings of Christianity emphasizing development of the theological thoughts on the Kingdom of God, Synoptic kerygma", "The Church changing from a religious movement to religious institution, their failure to the Jews, the Fall of Jerusalem in 70 AD", "Hellenistic Christianity and Jewish Christianity, factors that helped the spread of Christianity", "Re-interpretation of Jesus traditions in the light of Easter experience are taught"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 323', 'New Testament Theological Framework', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'first', 2, 'This course examines the origin of New Testament Theological motives, Mark''s predictions, Background of the Book of Revelation, New Testament Promises and Predictions, Resurrection and Immortality, Recovery of Eschatology, Messiahship and Messianic Hopes.', '["This course examines the origin of New Testament Theological motives, Mark''s predictions", "Background of the Book of Revelation, New Testament Promises and Predictions", "Resurrection and Immortality, Recovery of Eschatology, Messiahship and Messianic Hopes"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 331', 'History of Christianity in West Africa', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'first', 2, 'The aim of the course is to trace the history of the Church in West Africa from the Portuguese missions to the rise of independent churches. Emphasis will be placed on missionary activities, West African Response and patterns of religious change. The course also studies missionary activities and the growth and spread of churches in Nigeria from 19th to 21st Centuries, and what contributions the church has made to the development of Nigeria Proliferation of churches and its effects in the society.', '["The aim of the course is to trace the history of the Church in West Africa from the Portuguese missions to the rise of independent churches", "Emphasis will be placed on missionary activities, West African Response and patterns of religious change", "The course also studies missionary activities and the growth and spread of churches in Nigeria from 19th to 21st Centuries, and what contributions the church has made to the development of Nigeria Proliferation of churches and its effects in the society"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 301', 'Religious Interpretation of Society', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'first', 3, 'This course prepares and acquaints the students with practical everyday life situation facing them, the importance of self-transcendence and moral/transcendence in man and religion; Man and religion, Man and religion: Creation; mythical, biblical and traditional.', '["This course prepares and acquaints the students with practical everyday life situation facing them, the importance of self-transcendence and moral/transcendence in man and religion", "Man and religion: Creation; mythical, biblical and traditional"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 351', 'African Traditional Religion II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'first', 2, 'This course posits before students the in-depth contents of African culture and religion, starting from Chukwu, the Creator, to every other thing created. The significance of worship, sacrifice, ethics, life, death and eschatology. The role of the traditional religion in nation-building.', '["This course posits before students the in-depth contents of African culture and religion, starting from Chukwu, the Creator, to every other thing created", "The significance of worship, sacrifice, ethics, life, death and eschatology", "The role of the traditional religion in nation-building"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 314', 'Old Testament Prophets', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'second', 2, 'The course studies general introduction to Prophetism in Israel, comprising the Former and the Latter Prophets. It also takes on the major themes from the Prophets. Some of these include: the idea of election, responsibility of the nation and individuals before Yahweh, sacrifice, sovereignty of God, House of God, the Day of Yahweh, etc.', '["The course studies general introduction to Prophetism in Israel, comprising the Former and the Latter Prophets", "It also takes on the major themes from the Prophets", "Some of these include: the idea of election, responsibility of the nation and individuals before Yahweh, sacrifice, sovereignty of God, House of God, the Day of Yahweh, etc"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 322', 'Earliest Christianity: The Life and Work of St. Paul', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'second', 2, 'The course introduces students to major themes in the life, work and theology of Paul. The Jew and importance of Paul to Christian beginning is the beginning of the course. The significance of the Damascus Road experience of Paul, the Roman citizen are examined. The Call and Missionary Journeys, Paul''s Theological thoughts on the Law, man, righteousness - Justification, grace, faith, freedom, Christian ethics, eschatology and Christology are examined from his letters. Pauline kerygma is juxtaposed with the Apostolic Kerygma.', '["The course introduces students to major themes in the life, work and theology of Paul", "The significance of the Damascus Road experience of Paul, the Roman citizen are examined", "The Call and Missionary Journeys, Paul''s Theological thoughts on the Law, man, righteousness - Justification, grace, faith, freedom, Christian ethics, eschatology and Christology are examined from his letters", "Pauline kerygma is juxtaposed with the Apostolic Kerygma"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 324', 'New Testament Text I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'second', 2, 'This course is designed to acquaint students with the principles and methods of New Testament Exegesis and Hermeneutics. These principles and methods of exegesis are applied to the main teachings and issues in the Epistle to the Romans and Acts of Apostles with Selected passages in Greek or English languages. Authorship, Dates and Content of these books are examined.', '["This course is designed to acquaint students with the principles and methods of New Testament Exegesis and Hermeneutics", "These principles and methods of exegesis are applied to the main teachings and issues in the Epistle to the Romans and Acts of Apostles with Selected passages in Greek or English languages", "Authorship, Dates and Content of these books are examined"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 332', 'Christian History and Doctrine II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'second', 2, 'The history of the medieval church with special Reference to its reform movements. Theology of reformation and the Christian missions. Reference is made to the doctrines of scripture and tradition faith and work, and grace and merit.', '["The history of the medieval church with special Reference to its reform movements", "Theology of reformation and the Christian missions", "Reference is made to the doctrines of scripture and tradition faith and work, and grace and merit"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 334', 'African Church Fathers', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'second', 2, 'The aim of the course is to guide the students to know the history of the African Church Fathers in the early Christian Church, with special reference to the significant role, and contributions made by the African Church Leaders in the defence, propagation, growth and the expansion of the Christian Church in the early church.', '["The aim of the course is to guide the students to know the history of the African Church Fathers in the early Christian Church", "With special reference to the significant role, and contributions made by the African Church Leaders in the defence, propagation, growth and the expansion of the Christian Church in the early church"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 336', 'Reformation Era 1500-1650', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'second', 2, 'The purpose of this course is to examine the causes of the Reformation started by Martin Luther; the doctrinal teachings of the Reformers. The Counter Reformation by Roman Catholic Church and the general consequences of the Reformation in Europe.', '["The purpose of this course is to examine the causes of the Reformation started by Martin Luther; the doctrinal teachings of the Reformers", "The Counter Reformation by Roman Catholic Church and the general consequences of the Reformation in Europe"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 341', 'Religious Interpretation of Society', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'first', 2, 'This course prepares and acquaints the students with practical everyday life situation facing them, the importance of self-transcendence and moral/transcendence. Man and religion, Man and religion; Creation: mythical, biblical and traditional.', '["This course prepares and acquaints the students with practical everyday life situation facing them, the importance of self-transcendence and moral/transcendence", "Man and religion; Creation: mythical, biblical and traditional"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 342', 'Man and His Culture', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'second', 2, 'This course studies man and his significance vis-à-vis the culture which he has built. The concept of culture as a creation of the society is examined. It further examines the relationship between culture and religion as well as culture and education. Recent trends in inculturation and acculturation are studied. The exclusive relationship over other lower creation of monkeys/ primates are examined.', '["This course studies man and his significance vis-à-vis the culture which he has built", "The concept of culture as a creation of the society is examined. It further examines the relationship between culture and religion as well as culture and education", "Recent trends in inculturation and acculturation are studied. The exclusive relationship over other lower creation of monkeys/primates are examined"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 343', 'The Relevance of Religion to Man', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'first', 2, 'The aim of this course is to make students realise that religion is a dominant and fundamental force to be reckoned with, otherwise, the society of which man lives becomes chaotic. Emphasis is placed on the value of religion to man especially as a character builder, motivator, and their welfare package. The importance of achieving freedom is emphasized through this.', '["The aim of this course is to make students realise that religion is a dominant and fundamental force to be reckoned with, otherwise, the society of which man lives becomes chaotic", "Emphasis is placed on the value of religion to man especially as a character builder, motivator, and their welfare package", "The importance of achieving freedom is emphasized through this"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 344', 'Religion and Human Values II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'second', 2, 'This is based on Rel 106. The course caters to further raise such important questions as human healthy existence such as honesty, care for the needy, mutual co-existence and respect, values as opposed to ill-gotten wealth, obedience to the law of the nation, work, egoism, unity of purpose and what others have seen as the immediate society and the nation at large.', '["This is based on Rel 106. The course caters to further raise such important questions as human healthy existence such as honesty, care for the needy, mutual co-existence and respect", "Values as opposed to ill-gotten wealth, obedience to the law of the nation, work, egoism, unity of purpose", "What others have seen as the immediate society and the nation at large"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 352', 'African Traditional Religion III', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'second', 2, 'The course challenges the students to the continuity of or discontinuity of religion. Comparative issues among the three major religions in Nigeria in nation building are considered. Contemporary child abduction, Title-taking, Burial rites, etc as well as the role of traditional religion in nation building are considered.', '["The course challenges the students to the continuity of or discontinuity of religion", "Comparative issues among the three major religions in Nigeria in nation building are considered", "Contemporary child abduction, Title-taking, Burial rites, etc as well as the role of traditional religion in nation building are considered"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 362', 'Religious Ethics II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'second', 2, 'The focus is to give from a broad range of practical day-to-day ethical problems facing the nation, the development of moral codes to the students and to exert a strong influence on the presented and possible arguments on various themes are assessed.', '["The focus is to give from a broad range of practical day-to-day ethical problems facing the nation, the development of moral codes to the students", "To exert a strong influence on the presented and possible arguments on various themes are assessed"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 411', 'Hebrew Poetry', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '400 Level', 'first', 2, 'The nature and main features of Hebrew poetry are studied based on specific Hebrew texts from the Psalter, Wisdom, Proverbs and Lamentation.', '["The nature and main features of Hebrew poetry are studied based on specific Hebrew texts from the Psalter, Wisdom, Proverbs and Lamentation"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 413', 'Literature of the Old Testament I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '400 Level', 'first', 3, 'The course looks at the early development of literary studies of Old Testament especially as it concerns Transmission, Text and Canon. It also identifies the lost books of Old Testament which were used in the writing of some parts of the Bible, e.g. the Book of War of Yahweh, the book of Josiah, the Book of righteousness, etc.', '["The course looks at the early development of literary studies of Old Testament especially as it concerns Transmission, Text and Canon", "It also identifies the lost books of Old Testament which were used in the writing of some parts of the Bible, e.g. the Book of War of Yahweh, the book of Josiah, the Book of righteousness, etc"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 421', 'Close of the New Testament Era', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '400 Level', 'first', 3, 'Movement and development in early Christianity up to the close of the writing of the canonical books of the New Testament for Christianity are also taught. Biblical criticism, Jesus and Christ of history and the New Testament Quests are examined. How the need for Church Government and discipline, and heresy became a major and critical issue in the early Church.', '["Movement and development in early Christianity up to the close of the writing of the canonical books of the New Testament for Christianity are also taught", "Biblical criticism, Jesus and Christ of history and the New Testament Quests are examined", "How the need for Church Government and discipline, and heresy became a major and critical issue in the early Church"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 431', 'Christian History and Doctrine III', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '400 Level', 'first', 3, 'The history of the Church from 1750 to the present with special reference to the evangelical revival, the missionary movement, developments of and challenges to liberal thought in Roman Catholic and protestant churches; the ecumenical movement; eschatology, atonement, natural theology.', '["The history of the Church from 1750 to the present with special reference to the evangelical revival, the missionary movement", "Developments of and challenges to liberal thought in Roman Catholic and protestant churches", "The ecumenical movement; eschatology, atonement, natural theology"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 437', 'Modern African Religious Thought', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '400 Level', 'first', 3, 'The aim of this course is to examine the new trends in theological development in Africa scene. It also examines the religious thoughts and ideas that have emerged in the African scene since the emergence of Christianity in West Africa. The focus is on the ideas and thoughts that led to the development of Black Theology, Liberation Theology and emergent of African Theology in response to the Gospel in West Africa.', '["The aim of this course is to examine the new trends in theological development in Africa scene", "It also examines the religious thoughts and ideas that have emerged in the African scene since the emergence of Christianity in West Africa", "The focus is on the ideas and thoughts that led to the development of Black Theology, Liberation Theology and emergent of African Theology in response to the Gospel in West Africa"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 443', 'Religion and Culture in Contemporary Society', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '400 Level', 'first', 2, 'The aim of this course is to help the students familiarise themselves with the functions of culture within religion that is inseparably interwoven with it. Since religion is an integral part of Nigerian culture with other cultures as it touches on Christian religion. The impact of modernity, urbanization, industrialization, Pentecostalism on African culture will be examined.', '["The aim of this course is to help the students familiarise themselves with the functions of culture within religion that is inseparably interwoven with it", "Since religion is an integral part of Nigerian culture with other cultures as it touches on Christian religion", "The impact of modernity, urbanization, industrialization, Pentecostalism on African culture will be examined"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 471', 'Islamic Ethics', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '400 Level', 'first', 2, 'This course is an introduction to the study of Islamic ethics. Its main aim is to examine the relation between the ethical elements in Islam, and the moral values in general. The course content includes the study of the close link between religion and ethics in Islam, such as the Quran, Hadith, Sunna, the Five Pillars and Ijoma. The main sources of Islamic ethics, such as the Quran, Hadith, Sunna, the Five Pillars and Ijoma are considered. The importance of the Sharia Legal Code in Islam is examined. Basic ethical elements such as the concept of social justice, sin and forgiveness, predestination, day of judgment or resurrection, al-haram and al-halal (prohibitions and lawful acts in Islam) are examined in detail.', '["This course is an introduction to the study of Islamic ethics. Its main aim is to examine the relation between the ethical elements in Islam, and the moral values in general", "The course content includes the study of the close link between religion and ethics in Islam, such as the Quran, Hadith, Sunna, the Five Pillars and Ijoma", "The importance of the Sharia Legal Code in Islam is examined", "Basic ethical elements such as the concept of social justice, sin and forgiveness, predestination, day of judgment or resurrection, al-haram and al-halal (prohibitions and lawful acts in Islam) are examined in detail"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 481', 'Departmental Seminar', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '400 Level', 'first', 2, 'The course aims at exposing students to issues of practice of religion in a pluralistic society like Nigeria; state-religious bodies'' relationships; the issues of Christianity and native cultures and traditions. Seminar Papers are presented by students.', '["The course aims at exposing students to issues of practice of religion in a pluralistic society like Nigeria; state-religious bodies'' relationships", "The issues of Christianity and native cultures and traditions", "Seminar Papers are presented by students"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 491', 'Project Tutorials', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '400 Level', 'first', 1, 'This course examines the meaning and nature of academic research. Field and Library forms of research methods are examined. Different methods of collecting and collating data form core part of the tutorial; e.g. interview, questionnaire, respondent, use of library material, Internet, etc. Different methods of documentation, including American Psychological Association (APA), Modern Language Association and Classic Styles are taught. The use of the internet for research is also expected to have a hands-on experience in internet browsing.', '["This course examines the meaning and nature of academic research. Field and Library forms of research methods are examined", "Different methods of collecting and collating data form core part of the tutorial; e.g. interview, questionnaire, respondent, use of library material, Internet, etc", "Different methods of documentation, including American Psychological Association (APA), Modern Language Association and Classic Styles are taught", "The use of the internet for research is also expected to have a hands-on experience in internet browsing"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 414', 'Literature of the Old Testament II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '400 Level', 'second', 3, 'This course looks deep into the three sections of Old Testament literature which include the Torah (Law), Nabi''im (Prophets) and the Ketubim (Writings) noting their places to the history and religion of Israel. The religion and history of the Israelites are interwoven and interrelated. This accounts for the significant places of the Old Testament literature.', '["This course looks deep into the three sections of Old Testament literature which include the Torah (Law), Nabi''im (Prophets) and the Ketubim (Writings) noting their places to the history and religion of Israel", "The religion and history of the Israelites are interwoven and interrelated", "This accounts for the significant places of the Old Testament literature"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 416', 'Pseudo-Epigraphic Books of the Old Testament', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '400 Level', 'second', 2, 'The course studies some interesting themes from the pseudo-epigraphical works of the inter-testamental period. Some of these themes like the kingdom of heaven, son of man, end of ages, and abuses of these materials. Myths surrounding these materials, students in understanding the salient topics and themes in these materials.', '["The course studies some interesting themes from the pseudo-epigraphical works of the inter-testamental period", "Some of these themes like the kingdom of heaven, son of man, end of ages, and abuses of these materials", "Myths surrounding these materials, students in understanding the salient topics and themes in these materials"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 432', 'New Testament Text II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '400 Level', 'second', 3, 'This course applies the principles of Exegesis and Hermeneutics in the main teachings and issues as contained in John''s gospel and the Epistles of John. Selected passages are studied in Greek or English. Exegesis of selected passages is applied to the African society, Authorship, and Contents of these books are examined. The significance of the "I Am Statement" and the Signs are examined.', '["This course applies the principles of Exegesis and Hermeneutics in the main teachings and issues as contained in John''s gospel and the Epistles of John", "Selected passages are studied in Greek or English. Exegesis of selected passages is applied to the African society", "Date, Authorship, and Contents of these books are examined", "The significance of the \"I Am Statement\" and the Signs are examined"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 444', 'Theodicy', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '400 Level', 'second', 2, 'This course discusses in detail the existence of evil in all its forms following the claim that God did not create evil and that He is wholly good. Augustine''s idea of the existence of evil and other ideas will be brought into focus.', '["This course discusses in detail the existence of evil in all its forms following the claim that God did not create evil and that He is wholly good", "Augustine''s idea of the existence of evil and other ideas will be brought into focus"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 456', 'Comparative Study of Religion in Africa', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '400 Level', 'second', 2, 'This course exposes students to trans-cultural study of some cultural traits of African countries within the reach of literature. The use of Max Muller model of comparative religion is studied. The major world religions are studied with a view to sift the common elements and their contrasting views. At the end students are exposed to various religious cultures and their attitudinal behaviours.', '["This course exposes students to trans-cultural study of some cultural traits of African countries within the reach of literature", "The use of Max Muller model of comparative religion is studied", "The major world religions are studied with a view to sift the common elements and their contrasting views", "At the end students are exposed to various religious cultures and their attitudinal behaviours"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 492', 'Project', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '400 Level', 'second', 6, 'Students are required to conduct a research on a problem topic that should be classified in a stress area. Their research report/long essay should follow a specified documentation pattern. The Departmental Board approves the subject of the research paper by the end of the penultimate year of study.', '["Students are required to conduct a research on a problem topic that should be classified in a stress area", "Their research report/long essay should follow a specified documentation pattern", "The Departmental Board approves the subject of the research paper by the end of the penultimate year of study"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('RCS 402', 'Religion and the Nigerian Nation', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '400 Level', 'second', 2, '', '[]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  -- Required ancillary / general studies / elective courses from other departments — real code/title/units from the timetable, description left blank pending a verified source.
  ('GSP 101', 'The Use of English I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'first', 2, 'Man, Society and Language - The Nature, Characteristics and Functions of Language, Human Communication & Language, The English Language and the Nigerian society, World English, Levels and Varieties of English — formal, informal, standard, etc., English in Literature and the Media.

Vocabulary of English - Types, Method of Vocabulary Development, Synonyms, Antonyms, Homonyms, Acronyms, Paronyms, Affixation and other morphological processes, English Language Register, diatypes and dialects.

Listening skill - The listening skill discussed as a receptive and reciprocal activity, Nature, Types, Purposes and Factors that affect Listening, Strategies and Aids for Effective Listening.

Reading Skill - The concept of reading as a linguistic organization and a vehicle of communication. Reading Problems, Levels of Reading, Types of Reading, Causes and Remedies of Reading Failures, Reading Techniques & Strategies (Scanning, Skimming, Phrase reading, Intensive & Extensive reading, Exploiting the topic sentence for main ideas), Reading for details, Reading for evaluation and inference, Reading with questions - SQ3R, PR3, Methods for understanding difficult words in a reading text, Literature reading for study, analysis and comment.

Speaking & Communication Skills - Nature, Process & Development, Principles of Public Speech Making and Social Interaction, The Speech Sounds of English and their Articulation, Phonetic Transcription and Practical Speech Work.

Study Techniques - Choosing study centers and discussion groups, Note-taking during lectures, and from audio-visual equipment, Note-making techniques during private reading and literature search, Summary & Transcoding Techniques, Retrieving information from notes, The dictionary as a study guide.

Basic Research Methods & Term Paper Writing - Research – meaning & nature, Types & Methodology; Data in the Research Process, The Research Report, Process and Techniques, Documentation in Research Reports: Process, Types and Methods, Abbreviations in Research Reports, The term paper as a miniature research report, Practical term paper writing.

Course Evaluation & Grading - Students must attend at least 75% of the lectures to qualify for examination in the course.', '["Man, Society and Language - The Nature, Characteristics and Functions of Language, Human Communication & Language, World English, Levels and Varieties of English", "Vocabulary of English - Types, Method of Vocabulary Development, Synonyms, Antonyms, Homonyms, Acronyms, Paronyms, Affixation and other morphological processes", "Listening skill - Nature, Types, Purposes and Factors that affect Listening, Strategies and Aids for Effective Listening", "Reading Skill - Reading Problems, Levels and Types of Reading, Causes and Remedies of Reading Failures, Reading Techniques & Strategies, Reading for evaluation and inference", "Speaking & Communication Skills - Principles of Public Speech Making and Social Interaction, Phonetic Transcription and Practical Speech Work", "Study Techniques - Note-taking, Note-making, Summary & Transcoding Techniques", "Basic Research Methods & Term Paper Writing - The Research Report, Documentation, Abbreviations, practical term paper writing"]'::jsonb, 'Department of Mechanical Engineering handbook'),
  ('GSP 111', 'Use of the Library and Study Skill', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'first', 2, 'Overview of Library: concepts, history, types and functions. Uses in academic libraries; organization of university library and library users. Library processes and procedures. Acquisition process, Cataloging and classification, LC Scheme, in-House Scheme, DDC. Serials process and circulation processes. Access tools in Library resources: Library catalogues, Indexes, Abstracts, Current contents information in the library. Reference sources: types of reference sources and services. Web resources and online resources. Overview of Databases, Online search strategies for information retrieval. Referencing and citation styles for information reporting. Concept of plagiarism. Learning skills and research skills, ICT skillsets: types of learning and information policies.', '["Overview of Library: concepts, history, types and functions. Uses in academic libraries; organization of university library and library users", "Library processes and procedures. Acquisition process, Cataloging and classification, LC Scheme, in-House Scheme, DDC. Serials process and circulation processes", "Access tools in Library resources: Library catalogues, Indexes, Abstracts, Current contents information", "Reference sources: types of reference sources and services. Web resources and online resources", "Overview of Databases, Online search strategies for information retrieval. Referencing and citation styles for information reporting. Concept of plagiarism", "Learning skills and research skills, ICT skillsets: types of learning and information policies"]'::jsonb, 'Department of Mechanical Engineering handbook'),
  ('ACH 101', 'Fundamentals of Archaeology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('ECO 101', 'Principles of Economics I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'first', 2, 'Nature and significance of Economics; The methodology of economics; Economic tools of analysis; Theories of demand and supply; Elementary analysis; Dynamic theory of price; Elements of price theory; Production theory: Output, cost, law of diminishing returns; Market structure: Perfect competition, monopoly, oligopoly etc; Elementary theory of welfare economics; Determinants for and pricing of productive factors; Interest rate and profit.', '["Nature and significance of Economics", "The methodology of economics", "Economic tools of analysis", "Theories of demand and supply", "Elementary analysis", "Dynamic theory of price", "Elements of price theory", "Production theory: Output, cost, law of diminishing returns", "Market structure: Perfect competition, monopoly, oligopoly etc", "Elementary theory of welfare economics", "Determinants for and pricing of productive factors", "Interest rate and profit"]'::jsonb, 'Department of Economics handbook'),
  ('FRE 101', 'Elementary French I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'first', 2, 'Elective.', '[]'::jsonb, 'Department of Pure and Industrial Chemistry undergraduate programme'),
  ('PHL 101', 'Introduction to Philosophy I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'first', 2, 'The nature and the principal branches of Philosophy: philosophical problems of other disciplines; introduction to African Philosophical Thought, Philosophical method; illustrations from the history of philosophy.', '["The nature and the principal branches of Philosophy", "Philosophical problems of other disciplines", "Introduction to African Philosophical Thought, Philosophical method", "Illustrations from the history of philosophy"]'::jsonb, 'Department of Philosophy handbook'),
  ('ANT 102', 'Introduction to Anthropology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'first', 4, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('GSP 102', 'The Use of English II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '100 Level', 'second', 2, 'Part A: Basic Grammar: Introduction. The concept of grammar and its place in language teaching and learning. Parts of speech and their functions (treated in detail). Closed and open class items in parts of speech, Nominalization, Grammatical Structures: the phrase, the clause and the sentence. Elementary Clause Analysis, Sentence Types, Elements and Patterns. Agreement (Grammatical agreement, Notional agreement, Proximity agreement) Agreement with the correlatives. Direct and Reported Speech, Error typology identification and correction.

Part B: Varieties of writing. Introduction (The Meaning, Nature and Purpose of Writing, Writing Types or Genres and their Characteristics). The paragraph as the basic unit of an essay (Types, Development of the Paragraph, Methods of Paragraph Development, The thesis statement). Point of view and style in writing. Qualities of a good piece of writing: Form, Diction and Content in writing. The Mechanics of Writing: punctuation, spelling and capitalization.

Part C: Writing Genres - Planning and choosing your theme. Deciding your genre. Choosing and developing your plot. Point of view, setting and characterization. Using the language that works. Essay Writing — Narration, Description, Exposition and Argumentation. Technical Writing: Letter Writing, Memorandum Writing, Speech Writing, Agenda and Minutes, own story for practice, Computer-linked writing, types, style, language, and process.', '["Part A: Basic Grammar - The concept of grammar, Parts of speech, Grammatical Structures, Sentence Types, Agreement, Direct and Reported Speech, Error typology", "Part B: Varieties of writing - Meaning, Nature and Purpose of Writing, the paragraph as the basic unit of an essay, the thesis statement, Qualities of a good piece of writing, Mechanics of Writing", "Part C: Writing Genres - Planning and choosing your theme, plot, point of view, setting and characterization", "Essay Writing - Narration, Description, Exposition and Argumentation", "Technical Writing - Letter Writing, Memorandum Writing, Speech Writing, Agenda and Minutes"]'::jsonb, 'Department of Mechanical Engineering handbook'),
  ('GSP 105', 'Natural Science I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('GSP 201', 'Peace and Conflict Resolution I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('HIS 111', 'Nigeria before 1900', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('SOC 203', 'Sociology of Knowledge, Science and Technology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('PHL 251', 'African Philosophy I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'first', 2, 'Descriptive and analytic examination of African traditional thought, its world views and main characteristics (religious, moral, mythological etc). Elucidation of its ontological notions of force, being and spirit, and cosmological notions (life, death, mystical power destiny, nature, etc). Institutional devices embodying African traditional thought; relation of this thought to its environment.', '["Descriptive and analytic examination of African traditional thought, its world views and main characteristics", "Elucidation of its ontological notions of force, being and spirit, and cosmological notions", "Institutional devices embodying African traditional thought; relation of this thought to its environment"]'::jsonb, 'Department of Philosophy handbook'),
  ('PSY 261', 'Psychology of Personality', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '200 Level', 'first', 2, 'The problem of personality definitions. Personality types, personality theories; psychometric and trait approach to personality, psychoanalytic approach to personality, social learning approach to personality, humanistic approach to personality. Critical implications.', '["The problem of personality definitions", "Personality types, personality theories; psychometric and trait approach to personality", "Psychoanalytic approach to personality, social learning approach to personality, humanistic approach to personality", "Critical implications"]'::jsonb, 'Department of Psychology handbook'),
