  ('COS 101', 'Introduction to Computer Science', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'first', 2, 'Concepts of hardware and software; basic subsystems of a digital computer; characteristics of a digital computer; devices/media; types/classes of computer emphasising the PC; history of computers and their generations. Problem-solving: algorithm, flowchart, pseudocode, program/data, running a program. Programming: introduction to Java/BASIC programming language syntax and programming. Booting and shutdown; types of operating system; user interface; managing information, computer malware (virus, etc); computer network; internet and web usage, e-mail, instant messaging, etc. Office applications; use of a statistical package and a database management system.', '["Concepts of hardware and software","basic subsystems of a digital computer","characteristics of a digital computer","devices/media","types/classes of computer emphasising the PC","history of computers and their generations","Problem-solving: algorithm, flowchart, pseudocode, program/data, running a program","Programming: introduction to Java/BASIC programming language syntax and programming","Booting and shutdown","types of operating system","user interface","managing information, computer malware (virus, etc)","computer network","internet and web usage, e-mail, instant messaging, etc","Office applications","use of a statistical package and a database management system"]'::jsonb, 'Department of Computer Science course outline'),
  ('CED 341', 'Courses on Entrepreneurial Development and Research I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('HIS 311', 'Nigeria from 1900 to 1960', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('RCS 311', 'Hebrew Grammar and Syntax I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'first', 2, 'This course is a continuation of Rel 211 & 213; Parsing of the causative o- Hiphil and the passive – Hophal; verbal suffixes, use of preposition, verbs with guttural or weak letters as radicals. Students will become conversant with Hebrew grammatical components. They will also translate from Hebrew to English and vice versa.', '["This course is a continuation of Rel 211 & 213; Parsing of the causative o- Hiphil and the passive – Hophal", "Verbal suffixes, use of preposition, verbs with guttural or weak letters as radicals", "Students will become conversant with Hebrew grammatical components. They will also translate from Hebrew to English and vice versa"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
  ('PHL 351', 'African Philosophy II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'first', 2, 'Critical examination of the background of contemporary African thought, or urban culture on traditional thought. The quest for identity and pan-Africanism, nationalism, emergency of social philosophies (negritude, African socialism, communalism, etc); Independence and the transition; the drive towards positivism. The works and lives of Senghor, Nkrumah and Azikiwe may be used as case studies.', '["Critical examination of the background of contemporary African thought, or urban culture on traditional thought", "The quest for identity and pan-Africanism, nationalism, emergency of social philosophies (negritude, African socialism, communalism, etc)", "Independence and the transition; the drive towards positivism", "The works and lives of Senghor, Nkrumah and Azikiwe may be used as case studies"]'::jsonb, 'Department of Philosophy handbook'),
  ('COS 304', 'Computer Applications', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'second', 2, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('CED 342', 'Courses on Entrepreneurial Development and Research II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'second', 2, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('RCS 312', 'Hebrew Grammar and Syntax II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Religion and Cultural Studies', '300 Level', 'second', 2, 'The course helps the students in applying all the grammar they have learnt in the translation of passages from Genesis and Judges. More technical differences in the biblical versions are identified.', '["The course helps the students in applying all the grammar they have learnt in the translation of passages from Genesis and Judges", "More technical differences in the biblical versions are identified"]'::jsonb, 'Department of Religion and Cultural Studies handbook'),
